"""Makes test/fixtures/attachment_reference.dart: one attachment file in
format v1 (lib/data/attachments/attachment_format.dart), written by an
independent implementation (Python, pyca/cryptography), so the tests prove
that the app reads the format as specified and that Android and Windows
agree with a third party (T5.1, PO 09-10-2026).

    python test/fixtures/make_attachment_reference.py

Needs `pip install cryptography`. Fixed inputs, so the output never changes.
"""
import base64
import hashlib
import hmac
import pathlib

from cryptography.hazmat.primitives.ciphers.aead import AESGCM

ATTACHMENTS_KEY = bytes(range(32))
ATTACHMENT_ID = '0192a3b4-c5d6-7e8f-9a0b-1c2d3e4f5a6b'
SALT = bytes(range(16, 32))
NONCE_PREFIX = bytes(range(1, 8))
SEGMENT_SHIFT = 10  # 1 KiB segments, so a small file has several
PLAINTEXT = (b'Offload reference attachment. ' * 84)[:2500]


def hkdf_sha256(ikm, salt, info, length):
    prk = hmac.new(salt, ikm, hashlib.sha256).digest()
    out, block, counter = b'', b'', 1
    while len(out) < length:
        block = hmac.new(prk, block + info + bytes([counter]), hashlib.sha256).digest()
        out += block
        counter += 1
    return out[:length]


header = (b'OFA' + bytes([1, SEGMENT_SHIFT, 0, 0, 0]) + SALT + NONCE_PREFIX + bytes([0]))
assert len(header) == 32
aad = header + ATTACHMENT_ID.encode()
key = hkdf_sha256(ATTACHMENTS_KEY, SALT,
                  ('eu.marandos.offload/attachment/v1/' + ATTACHMENT_ID).encode(), 32)
size = 1 << SEGMENT_SHIFT
segments = [PLAINTEXT[i:i + size] for i in range(0, len(PLAINTEXT), size)] or [b'']
body = b''
for index, segment in enumerate(segments):
    last = index == len(segments) - 1
    nonce = NONCE_PREFIX + index.to_bytes(4, 'big') + bytes([1 if last else 0])
    body += AESGCM(key).encrypt(nonce, segment, aad)
data = header + body

out = pathlib.Path(__file__).with_name('attachment_reference.dart')
encoded = base64.b64encode(data).decode()
lines = [encoded[i:i + 72] for i in range(0, len(encoded), 72)]
out.write_text(
    '// Generated by make_attachment_reference.py; do not edit.\n'
    '//\n'
    '// An attachment file in format v1, written with pyca/cryptography.\n'
    'library;\n\n'
    "import 'dart:convert';\n"
    "import 'dart:typed_data';\n\n"
    'final referenceAttachmentsKey = Uint8List.fromList(\n'
    '  List.generate(32, (i) => i),\n'
    ');\n\n'
    f"const referenceAttachmentId = '{ATTACHMENT_ID}';\n\n"
    '/// The plaintext: the line below repeated, cut at 2500 bytes.\n'
    "final referencePlaintext = ('Offload reference attachment. ' * 84)\n"
    '    .substring(0, 2500);\n\n'
    f"/// SHA-256 of [referencePlaintext].\n"
    f"const referenceSha256 = '{hashlib.sha256(PLAINTEXT).hexdigest()}';\n\n"
    'final referenceFile = base64.decode(\n'
    + ''.join(f"  '{line}'\n" for line in lines)
    + ');\n',
    encoding='utf-8',
    newline='\n',
)
print(f'{out}: {len(data)} bytes, {len(segments)} segments')
